import{_ as o,o as t,c as d,a2 as c}from"./chunks/framework.CdvW4CUT.js";const y=JSON.parse('{"title":"Processor 编译期字节码转换与接入配置","description":"","frontmatter":{},"headers":[],"relativePath":"1.21.4/sync/processor-and-network.md","filePath":"1.21.4/sync/processor-and-network.md"}'),i={name:"1.21.4/sync/processor-and-network.md"};function a(n,e,s,l,r,h){return t(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="processor-编译期字节码转换与接入配置" tabindex="-1">Processor 编译期字节码转换与接入配置 <a class="header-anchor" href="#processor-编译期字节码转换与接入配置" aria-label="Permalink to &quot;Processor 编译期字节码转换与接入配置&quot;">​</a></h1><p>为了实现 <code>@Sync</code> 与 <code>@LazySync</code> 的低侵入编写体验，<code>module.sync</code> 拆分了一个独立的字节码/注解处理器子项目 <code>anvillib-sync-processor-neoforge-1.21.4</code>，同时配合 NeoForge 网络注册与跨端查询工具 <code>SideUtil</code> 运行。</p><h2 id="gradle-接入说明" tabindex="-1">Gradle 接入说明 <a class="header-anchor" href="#gradle-接入说明" aria-label="Permalink to &quot;Gradle 接入说明&quot;">​</a></h2><p>如果模组直接引入完整 <code>anvillib</code>（或在开发期单独依赖子模块 <code>module.sync</code>），需要注意同步处理器与底包模块依赖（1.21.4 坐标系如下）：</p><div class="language-kotlin vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">kotlin</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dependencies</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    implementation</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;dev.anvilcraft.lib:anvillib-sync-neoforge-1.21.4:&lt;version&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // Processor 与相关运行时模块（codec / network / util）已作为传递依赖/JarJar 包含于对应构件中；</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // 若单独拆模块构建或启用编译期处理器配置，对应构件名为：</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // dev.anvilcraft.lib:anvillib-sync-processor-neoforge-1.21.4</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // dev.anvilcraft.lib:anvillib-codec-neoforge-1.21.4</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // dev.anvilcraft.lib:anvillib-network-neoforge-1.21.4</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // dev.anvilcraft.lib:anvillib-util-neoforge-1.21.4</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="编译期-类加载变换流程-processor" tabindex="-1">编译期 / 类加载变换流程 (<code>processor</code>) <a class="header-anchor" href="#编译期-类加载变换流程-processor" aria-label="Permalink to &quot;编译期 / 类加载变换流程 (`processor`)&quot;">​</a></h2><p>子模块 <code>module.sync/processor</code> 中的核心组件协作完成同步代码增强与目标索引生成：</p><ol><li><strong><code>SyncTargetIndex</code></strong>：在编译或构建扫描阶段提取所有标记 <code>@Sync</code> 与 <code>@LazySync</code> 的类及字段元数据，供运行时 <code>SyncConfigManager.compileContent()</code> 快速建表，避免运行时全类路径反射扫描。</li><li><strong><code>SyncBytecodeInjector</code></strong>：在转换管线中为带同步特征的目标字段/包装属性织入字段写拦截或访问钩子，并在构建期注入关联追踪辅助逻辑，保证对对象成员修改可以自动触发脏状态更新。</li></ol><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>尽量使用基本类型、原版常用类型（<code>BlockPos</code>、<code>ResourceLocation</code>、<code>ItemStack</code>、<code>CompoundTag</code> 等）或已通过 <code>CodecUtil</code> / <code>StreamCodecUtil</code> 存在预设序列化器的类型作为 <code>@LazySync</code> 字段，可获得零额外配置的自动编码能力。</p></div><h2 id="网络协议与跨端辅助-anvillibsyncnetwork-与-sideutil" tabindex="-1">网络协议与跨端辅助：<code>AnvilLibSyncNetwork</code> 与 <code>SideUtil</code> <a class="header-anchor" href="#网络协议与跨端辅助-anvillibsyncnetwork-与-sideutil" aria-label="Permalink to &quot;网络协议与跨端辅助：`AnvilLibSyncNetwork` 与 `SideUtil`&quot;">​</a></h2><h3 id="数据包负载-payload-一览" tabindex="-1">数据包负载 (<code>Payload</code>) 一览 <a class="header-anchor" href="#数据包负载-payload-一览" aria-label="Permalink to &quot;数据包负载 (`Payload`) 一览&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Payload 类</th><th>通道 ID</th><th>流向与职责</th></tr></thead><tbody><tr><td><code>SyncConfigurationPayload</code></td><td><code>anvillib_sync:sync_config</code></td><td><code>S2C</code>（Configuration 阶段）：下发服务端 <code>SyncConfigManager</code> 的 <code>Map&lt;Integer, String&gt;</code> 字段 ID 映射表</td></tr><tr><td><code>SyncConfigurationFinishPayload</code></td><td><code>anvillib_sync:sync_config_finish</code></td><td><code>C2S</code>（Configuration 阶段）：客户端确认映射表加载完成，允许推进后续连接阶段</td></tr><tr><td><code>SyncPayload</code></td><td><code>anvillib_sync:sync</code></td><td>双向 (<code>IBidirectionalPacket</code>)：单字段 <code>SyncProxy</code> 即时更新同步包</td></tr><tr><td><code>LazySyncPayload</code></td><td><code>anvillib_sync:lazy_sync</code></td><td>双向 (<code>IBidirectionalPacket</code>)：按对象分组聚合单个 Tick 内全部修改字段 <code>List&lt;FieldChange&gt;</code> 的增量同步包</td></tr></tbody></table><p>所有网络处理器均由 <code>AnvilLibSyncNetwork.register(RegisterPayloadHandlersEvent)</code> 在协议版本 <code>&quot;1&quot;</code> 下统一注册。</p><h3 id="sideutil-跨端发包与目标解析工具" tabindex="-1"><code>SideUtil</code> 跨端发包与目标解析工具 <a class="header-anchor" href="#sideutil-跨端发包与目标解析工具" aria-label="Permalink to &quot;`SideUtil` 跨端发包与目标解析工具&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方法签名</th><th>返回值</th><th>说明</th></tr></thead><tbody><tr><td><code>SideUtil.isServer()</code></td><td><code>boolean</code></td><td>基于 <code>FMLEnvironment.dist</code> 与 <code>LogicalSide</code> 判断当前是否运行于逻辑服务端线程</td></tr><tr><td><code>SideUtil.registryAccess()</code></td><td><code>@Nullable RegistryAccess</code></td><td>安全获取当前环境可用注册表访问器（服务端从 <code>ServerLifecycleHooks.getCurrentServer()</code> 取，客户端从 <code>Minecraft.getInstance().level</code> 取）</td></tr><tr><td><code>SideUtil.entityFinder(IPayloadContext context, UUID uuid)</code></td><td><code>@Nullable Entity</code></td><td>根据收到数据包的逻辑侧，从对应维度查找指定 <code>UUID</code> 的实体实例</td></tr><tr><td><code>SideUtil.blockEntityFinder(IPayloadContext context, BlockPos blockPos)</code></td><td><code>@Nullable BlockEntity</code></td><td>从当前数据包关联维度定位对应坐标的 <code>BlockEntity</code></td></tr><tr><td><code>SideUtil.createFriendlyByteBuf(ByteBuf byteBuf)</code></td><td><code>FriendlyByteBuf</code> / <code>RegistryFriendlyByteBuf</code></td><td>在需要携带注册表上下文的编码过程中按当前可用 <code>RegistryAccess</code> 构造缓冲封装</td></tr><tr><td><code>SideUtil.send(T target, SyncProxy&lt;?&gt; proxy, ...)</code> / <code>serverSend(...)</code> / <code>clientSend(...)</code></td><td><code>void</code></td><td>自动根据发包实体/区块追踪状态将增量同步包分发给需要同步的观察玩家或发送回服务端</td></tr></tbody></table>',15)])])}const k=o(i,[["render",a]]);export{y as __pageData,k as default};
